const input = $input.first().json;
// Recover ticket fields from a normal webhook body or legacy nested webhook bodies.
const allowed = ['ticketId','title','description','category','priority','assignedTeam','status','createdAt','aiReason','aiSuggestion','suggestedResponse','deduplication','alert','sla','actor'];
const layers = [];
let value = input;
for (let depth = 0; depth < 16; depth++) {
  if (typeof value === 'string') value = JSON.parse(value);
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Ticket payload must be a JSON object');
  layers.push(value);
  if (!Object.prototype.hasOwnProperty.call(value, 'body')) break;
  value = value.body;
  if (depth === 15) throw new Error('Webhook body nesting is too deep');
}
const ticket = {};
const trace = [];
for (const layer of layers.reverse()) {
  for (const key of allowed) if (Object.prototype.hasOwnProperty.call(layer, key)) ticket[key] = layer[key];
  if (Array.isArray(layer.workflowTrace)) for (const entry of layer.workflowTrace) {
    if (typeof entry === 'string' && entry.length <= 80 && !trace.includes(entry)) trace.push(entry);
  }
}
ticket.workflowTrace = trace.slice(-32);
return [{ json: ticket }];

const input = $input.first().json;
const ticket = { ...input };
if (typeof ticket.ticketId !== 'string' || !ticket.ticketId.trim() || ticket.ticketId.length > 100) throw new Error('ticketId is required and must be at most 100 characters');
ticket.ticketId = ticket.ticketId.trim();
for (const key of ['title','description','category','priority','status','assignedTeam','aiReason','aiSuggestion','suggestedResponse']) {
  if (ticket[key] !== undefined && typeof ticket[key] !== 'string') throw new Error(key + ' must be a string');
}
if (ticket.title && ticket.title.length > 200) throw new Error('title is too long');
if (ticket.description && ticket.description.length > 10000) throw new Error('description is too long');
return [{ json: ticket }];

const input = $input.first().json;
const names = { critical: 'Critical', high: 'High', medium: 'Medium', low: 'Low' };
const raw = String(input.priority ?? 'Medium').trim().toLowerCase();
if (!Object.prototype.hasOwnProperty.call(names, raw)) throw new Error('priority must be Critical, High, Medium, or Low');
return [{ json: { ...input, priority: names[raw], sla: { targetHours: ({ Critical: 1, High: 4, Medium: 24, Low: 72 })[names[raw]] } } }];

const input = $input.first().json;
const source = input.createdAt == null ? 'received_at' : 'ticket_created_at';
const created = input.createdAt == null ? new Date() : new Date(input.createdAt);
if (!Number.isFinite(created.getTime())) throw new Error('createdAt must be a valid date');
const statusNames = { open: 'Open', 'in progress': 'In Progress', resolved: 'Resolved' };
const status = statusNames[String(input.status ?? 'Open').trim().toLowerCase()];
if (!status) throw new Error('status must be Open, In Progress, or Resolved');
return [{ json: { ...input, status, createdAt: created.toISOString(), sla: { ...input.sla, createdAtSource: source } } }];

const input = $input.first().json;
const due = new Date(new Date(input.createdAt).getTime() + input.sla.targetHours * 3600000);
return [{ json: { ...input, sla: { ...input.sla, dueAt: due.toISOString() } } }];

const input = $input.first().json;
const now = Date.now();
const due = new Date(input.sla.dueAt).getTime();
const resolved = input.status === 'Resolved';
const breached = !resolved && now > due;
return [{ json: { ...input, sla: { ...input.sla, breached, state: resolved ? 'resolved' : breached ? 'overdue' : 'within_target', evaluatedAt: new Date(now).toISOString(), overdueMinutes: breached ? Math.ceil((now - due) / 60000) : 0 } } }];

const input = $input.first().json;
const workflowTrace = [...(input.workflowTrace ?? [])];
if (!workflowTrace.includes('WF08')) workflowTrace.push('WF08');
return [{ json: { ...input, workflowTrace } }];

const input = $input.first().json;
const expectedTicketId = $('09 - Append Workflow Trace').first().json.ticketId;
if (input.processingComplete !== true || !input.auditLog || typeof input.auditLog.eventId !== 'string') throw new Error('Downstream workflow did not return a completed audit event');
if (input.ticketId !== expectedTicketId || input.auditLog.ticketId !== expectedTicketId) throw new Error('Downstream ticketId does not match the audit event');
return [{ json: input }];
